p.write_text('''def transform(grid):
    # Swap the two colors according to the demonstrated background/marker remap.
    vals = {v for row in grid for v in row}
    if len(vals) != 2:
        raise ValueError("expected two-color grid")
    background = max(vals, key=lambda c: sum(v == c for row in grid for v in row))
    marker = next(v for v in vals if v != background)
    if background == 5 and marker == 1:
        mapping = {5: 1, 1: 0}
    elif marker == 5:
        mapping = {background: 0, marker: background}
    else:
        raise ValueError("palette not evidenced")
    return [[mapping[v] for v in row] for row in grid]
